-- Current Live content batch. Apply offline after 001..008; stop on any error.
-- Keeps existing Imp5/template20105 and active session snapshots untouched.
-- All476 standard preview variants are represented after this migration: nine
-- supported active combinations (Imp5 plus eight70s),467 disabled candidates.
-- Disabled race0 / budget0 are explicit unknown sentinels, not measured values.
-- Only enabled rows are consumed by the runtime catalog. Named gaps are stored
-- separately; no same-class loadout or intermediate-level budget is inferred.
-- Free highest-rank powers use one local grant-only adapter, with captured native
-- current/max presentation. Paid ranks offer only a directly evidenced first
-- rank, retaining normal server allocation/point enforcement. Later ranks remain
-- unavailable. Ordinary AA definitions and balances are never modified.
-- Spell effects retain the local RoF2-compatible definitions. Known differences:
--7482HamstringII Base2 effect2 Live3/local1;7554SwarmofPainX formula effect1
-- Live1002/local108;7588EarthBindIII Base2 effect2 Live1/local0.
ALTER TABLE spirit_shroud_abilities
 ADD COLUMN IF NOT EXISTS display_rank INT UNSIGNED NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS display_max_rank INT UNSIGNED NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS display_total_cost INT NOT NULL DEFAULT -1;
CREATE TABLE IF NOT EXISTS spirit_shroud_content_gaps (
 template_id INT UNSIGNED NOT NULL,
 field_name VARCHAR(96) NOT NULL,
 reason VARCHAR(255) NOT NULL,
 PRIMARY KEY(template_id,field_name)
) ENGINE=InnoDB;
CREATE TEMPORARY TABLE shroud009_ability LIKE aa_ability;
CREATE TEMPORARY TABLE shroud009_rank LIKE aa_ranks;
CREATE TEMPORARY TABLE shroud009_effect LIKE aa_rank_effects;
CREATE TEMPORARY TABLE shroud009_template LIKE spirit_shroud_templates;
CREATE TEMPORARY TABLE shroud009_link LIKE spirit_shroud_abilities;
CREATE TEMPORARY TABLE shroud009_equipment LIKE spirit_shroud_starter_equipment;
CREATE TEMPORARY TABLE shroud009_gap LIKE spirit_shroud_content_gaps;
CREATE TEMPORARY TABLE shroud009_guard(ok TINYINT NOT NULL CHECK(ok=1)) ENGINE=InnoDB;
START TRANSACTION;
 NOT EXISTS(SELECT 1 FROM aa_ability a JOIN shroud009_ability e ON a.`id`=e.`id` WHERE NOT(a.`id`<=>e.`id`) OR NOT(a.`name`<=>e.`name`) OR NOT(a.`category`<=>e.`category`) OR NOT(a.`classes`<=>e.`classes`) OR NOT(a.`type`<=>e.`type`) OR NOT(a.`grant_only`<=>e.`grant_only`) OR NOT(a.`first_rank_id`<=>e.`first_rank_id`) OR NOT(a.`charges`<=>e.`charges`) OR NOT(a.`enabled`<=>e.`enabled`) OR NOT(a.`status`<=>e.`status`) OR NOT(a.`races`<=>e.`races`) OR NOT(a.`deities`<=>e.`deities`) OR NOT(a.`drakkin_heritage`<=>e.`drakkin_heritage`) OR NOT(a.`reset_on_death`<=>e.`reset_on_death`) OR NOT(a.`auto_grant_enabled`<=>e.`auto_grant_enabled`))
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a JOIN shroud009_rank e ON a.`id`=e.`id` WHERE NOT(a.`id`<=>e.`id`) OR NOT(a.`upper_hotkey_sid`<=>e.`upper_hotkey_sid`) OR NOT(a.`lower_hotkey_sid`<=>e.`lower_hotkey_sid`) OR NOT(a.`title_sid`<=>e.`title_sid`) OR NOT(a.`desc_sid`<=>e.`desc_sid`) OR NOT(a.`cost`<=>e.`cost`) OR NOT(a.`level_req`<=>e.`level_req`) OR NOT(a.`spell`<=>e.`spell`) OR NOT(a.`spell_type`<=>e.`spell_type`) OR NOT(a.`recast_time`<=>e.`recast_time`) OR NOT(a.`prev_id`<=>e.`prev_id`) OR NOT(a.`next_id`<=>e.`next_id`) OR NOT(a.`expansion`<=>e.`expansion`))
 AND NOT EXISTS(SELECT 1 FROM aa_rank_effects a JOIN shroud009_effect e ON a.`rank_id`=e.`rank_id` AND a.`slot`=e.`slot` WHERE NOT(a.`rank_id`<=>e.`rank_id`) OR NOT(a.`slot`<=>e.`slot`) OR NOT(a.`effect_id`<=>e.`effect_id`) OR NOT(a.`base1`<=>e.`base1`) OR NOT(a.`base2`<=>e.`base2`))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_templates a JOIN shroud009_template e ON a.`id`=e.`id` WHERE NOT(a.`id`<=>e.`id`) OR NOT(a.`progression_id`<=>e.`progression_id`) OR NOT(a.`branch_id`<=>e.`branch_id`) OR NOT(a.`level`<=>e.`level`) OR NOT(a.`race`<=>e.`race`) OR NOT(a.`class_id`<=>e.`class_id`) OR NOT(a.`gender`<=>e.`gender`) OR NOT(a.`hp`<=>e.`hp`) OR NOT(a.`mana`<=>e.`mana`) OR NOT(a.`endurance`<=>e.`endurance`) OR NOT(a.`base_stat`<=>e.`base_stat`) OR NOT(a.`unlock_xp`<=>e.`unlock_xp`) OR NOT(a.`name`<=>e.`name`) OR NOT(a.`description`<=>e.`description`) OR NOT(a.`progression_name`<=>e.`progression_name`) OR NOT(a.`branch_name`<=>e.`branch_name`) OR NOT(a.`enabled`<=>e.`enabled`) OR NOT(a.`content_version`<=>e.`content_version`) OR NOT(a.`verified`<=>e.`verified`) OR NOT(a.`test_only`<=>e.`test_only`) OR NOT(a.`evidence_ref`<=>e.`evidence_ref`) OR NOT(a.`monster_points`<=>e.`monster_points`) OR NOT(a.`stat_str`<=>e.`stat_str`) OR NOT(a.`stat_sta`<=>e.`stat_sta`) OR NOT(a.`stat_cha`<=>e.`stat_cha`) OR NOT(a.`stat_dex`<=>e.`stat_dex`) OR NOT(a.`stat_int`<=>e.`stat_int`) OR NOT(a.`stat_agi`<=>e.`stat_agi`) OR NOT(a.`stat_wis`<=>e.`stat_wis`) OR NOT(a.`resource_maxima`<=>e.`resource_maxima`) OR NOT(a.`model_size`<=>e.`model_size`) OR NOT(a.`entitlement_key`<=>e.`entitlement_key`) OR NOT(a.`native_hp`<=>e.`native_hp`) OR NOT(a.`native_mana`<=>e.`native_mana`) OR NOT(a.`native_endurance`<=>e.`native_endurance`) OR NOT(a.`native_hp_regen`<=>e.`native_hp_regen`) OR NOT(a.`native_mana_regen_sitting`<=>e.`native_mana_regen_sitting`) OR NOT(a.`native_mana_regen_standing`<=>e.`native_mana_regen_standing`) OR NOT(a.`native_endurance_regen`<=>e.`native_endurance_regen`) OR NOT(a.`native_cold`<=>e.`native_cold`) OR NOT(a.`native_fire`<=>e.`native_fire`) OR NOT(a.`native_magic`<=>e.`native_magic`) OR NOT(a.`native_disease`<=>e.`native_disease`) OR NOT(a.`native_poison`<=>e.`native_poison`) OR NOT(a.`native_additional_resist`<=>e.`native_additional_resist`) OR NOT(a.`native_corruption`<=>e.`native_corruption`) OR NOT(a.`native_ac`<=>e.`native_ac`) OR NOT(a.`native_attack`<=>e.`native_attack`) OR NOT(a.`native_unarmed_damage`<=>e.`native_unarmed_damage`) OR NOT(a.`native_unarmed_delay`<=>e.`native_unarmed_delay`))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_abilities a JOIN shroud009_link e ON a.`template_id`=e.`template_id` AND a.`rank_id`=e.`rank_id` WHERE NOT(a.`template_id`<=>e.`template_id`) OR NOT(a.`rank_id`<=>e.`rank_id`) OR NOT(a.`free_grant`<=>e.`free_grant`) OR NOT(a.`display_rank`<=>e.`display_rank`) OR NOT(a.`display_max_rank`<=>e.`display_max_rank`) OR NOT(a.`display_total_cost`<=>e.`display_total_cost`))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_starter_equipment a JOIN shroud009_equipment e ON a.`template_id`=e.`template_id` AND a.`slot_id`=e.`slot_id` WHERE NOT(a.`template_id`<=>e.`template_id`) OR NOT(a.`slot_id`<=>e.`slot_id`) OR NOT(a.`item_id`<=>e.`item_id`))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_content_gaps a JOIN shroud009_gap e ON a.`template_id`=e.`template_id` AND a.`field_name`=e.`field_name` WHERE NOT(a.`template_id`<=>e.`template_id`) OR NOT(a.`field_name`<=>e.`field_name`) OR NOT(a.`reason`<=>e.`reason`))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_state s JOIN shroud009_template e ON e.id=s.template_id)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_sessions s JOIN shroud009_template e ON e.id=s.template_id WHERE s.phase='active')
 AND NOT EXISTS(SELECT 1 FROM aa_rank_prereqs WHERE rank_id BETWEEN 48100 AND 48998 OR aa_id BETWEEN 48100 AND 48998)
 AND NOT EXISTS(SELECT 1 FROM aa_ranks WHERE prev_id BETWEEN 48100 AND 48998 OR next_id BETWEEN 48100 AND 48998)
 AND NOT EXISTS(SELECT 1 FROM aa_ability a LEFT JOIN shroud009_ability e ON e.id=a.id WHERE a.first_rank_id BETWEEN 48100 AND 48998 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_rank_effects a LEFT JOIN shroud009_effect e ON e.rank_id=a.rank_id AND e.slot=a.slot WHERE a.rank_id BETWEEN 48100 AND 48998 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_abilities a JOIN shroud009_ability e ON e.id=a.rank_id LEFT JOIN shroud009_link l ON l.template_id=a.template_id AND l.rank_id=a.rank_id WHERE l.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_spells a JOIN shroud009_template e ON e.id=a.template_id)
 AND NOT EXISTS(SELECT 1 FROM shroud009_rank r LEFT JOIN spells_new s ON s.id=r.spell WHERE r.spell>0 AND s.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM shroud009_equipment e LEFT JOIN items i ON i.id=e.item_id WHERE i.id IS NULL OR i.stackable<>0 OR i.evolvinglevel<>0)
 AND NOT EXISTS(SELECT 1 FROM character_alternate_abilities WHERE aa_id BETWEEN 48100 AND 48998)
 AND NOT EXISTS(SELECT 1 FROM shroud_original_character_alternate_abilities WHERE aa_id BETWEEN 48100 AND 48998)
 AND NOT EXISTS(SELECT 1 FROM aa_ability a LEFT JOIN shroud009_ability e ON e.id=a.id WHERE a.id BETWEEN 48100 AND 48998 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a LEFT JOIN shroud009_rank e ON e.id=a.id WHERE a.id BETWEEN 48100 AND 48998 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_abilities a JOIN shroud009_template t ON t.id=a.template_id LEFT JOIN shroud009_link e ON e.template_id=a.template_id AND e.rank_id=a.rank_id WHERE e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_starter_equipment a JOIN shroud009_template t ON t.id=a.template_id LEFT JOIN shroud009_equipment e ON e.template_id=a.template_id AND e.slot_id=a.slot_id WHERE e.slot_id IS NULL),1,0);
