INSERT INTO shroud009_guard SELECT IF(
INSERT INTO aa_ability SELECT * FROM shroud009_ability ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
INSERT INTO aa_ranks SELECT * FROM shroud009_rank ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
INSERT INTO aa_rank_effects SELECT * FROM shroud009_effect ON DUPLICATE KEY UPDATE `rank_id`=VALUES(`rank_id`);
INSERT INTO spirit_shroud_templates SELECT * FROM shroud009_template ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
INSERT INTO spirit_shroud_abilities SELECT * FROM shroud009_link ON DUPLICATE KEY UPDATE `rank_id`=VALUES(`rank_id`);
INSERT INTO spirit_shroud_starter_equipment SELECT * FROM shroud009_equipment ON DUPLICATE KEY UPDATE `item_id`=VALUES(`item_id`);
INSERT INTO spirit_shroud_content_gaps SELECT * FROM shroud009_gap ON DUPLICATE KEY UPDATE `template_id`=VALUES(`template_id`);
